    reg clk;
    reg reset;
    wire [4:0] q;

    // 2. Instantiate TopModule dut ( ... );
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .q(q)
    );

    // 3. Stimulus & self-checking:
    integer errors = 0;
    integer i;
    reg [4:0] expected;

    initial begin
        // Initialize clock
        clk = 0;
        reset = 1; // Start with reset active
        #5 reset = 0; // Release reset after 5 time units

        // Wait for a few clock cycles to observe output
        for (i = 0; i < 20; i = i + 1) begin
            #10 clk = ~clk; // Toggle clock
            #10 clk = ~clk; // Toggle clock again

            // Calculate expected output based on LFSR behavior
            if (i < 1) begin
                expected = 5'b00001; // Initial state after reset
            end else begin
                // Galois LFSR with taps at positions 5 and 3
                expected = {expected[4:1], expected[4] ^ expected[2]};
            end

            // Check output
            if (q !== expected) begin
                $display("Error at time %0t: Expected q = %b, got q = %b", $time, expected, q);
                errors = errors + 1;
            end
        end

        // Final check
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end
endmodule
